/**
 * Every lab, and every hidden switch, in one list (design-audit O5). The lab page `/bn/lab`
 * shows it; a page opened with `?lab=<id>` shows a small badge linking back.
 *
 * Rule: a new lab is added here in the same step it is built, and its decision row names it.
 *
 * Versions (O5, C): the latest version is always live (`?lab=<id>`). While two versions are
 * being compared, the earlier one stays live too (`?lab=<id>@<v>`, `live: true`); once decided,
 * its code goes and it stays here as its commit and screenshots (`public/labs/<id>/`).
 * Versions made before the lab page (1 Nov, 12:30) have their commit but no screenshot.
 */

export type LabStatus = "lab" | "on-page" | "dropped";

export type LabVersion = {
  v: number;
  /** Bangladesh time. */
  date: string;
  commit: string;
  note: string;
  decisions: string[];
  /** An earlier version kept live while it is compared with the latest. */
  live?: boolean;
  /** The last version of a stretch of work, the point where one piece was finished and the next begun; the page's version switch lists only these. */
  end?: boolean;
  /** A short label on the lab list, e.g. the build handed to the developers (O13, O14). */
  tag?: string;
  shots?: { desktop?: string; phone?: string };
};

export type Lab = {
  id: string;
  /** Earlier ids merged into this lab; their links still open it (O7). */
  aliases?: string[];
  /**
   * Lab ids the code still reads, each over a range of this lab's versions (O13): `lx` v1–53 are the old
   * lab `class` (offset 0), v54 on are lab `concept` (v2 on, offset 52) on top of class v53.
   */
  layers?: { id: string; from: number; to?: number; offset: number }[];
  title: string;
  summary: string;
  /** The page the lab runs on. */
  page: string;
  /** Where to look on that page. */
  anchor?: string;
  device: "desktop" | "phone" | "both";
  status: LabStatus;
  /** For a lab that went onto the page or was dropped: the decision that did it. */
  outcome?: string;
  versions: LabVersion[];
};

