        note: "টিচারের প্রশ্ন (পোল): টিচার স্টুডিও থেকে খুললে এক মিনিট থাকে, নিজে বন্ধ হয়; রেকর্ডিংয়ে একই মুহূর্তে আবার আসে। ফোনে ভিডিওর নিচে বটম শিট, বড় স্ক্রিনে ডানে নিচে কার্ড, ফুল স্ক্রিনে ডানে প্যানেল আর ভিডিও বাঁয়ে সরে; 'পরে' দিলে সময়সহ ছোট পিল; উত্তর দিলে ক্লাসের উত্তর বারে। নমুনা: ক্লাস ১-এ ০:১৫, ক্লাস ২-এ ৩১:০০। টিচার ইনবক্সের নিচে একই রকম কার্ডে হোমওয়ার্ক, টেনটেন, সিমুলেশন (P104)। এর আগে: ক্লাস ১ লাইভ, কাজের একটায় টিক নেই, ট্যাবে সংখ্যা নেই, ২ সেকেন্ড লোডিং, কতজন দেখছে শুধু কন্ট্রোলের সাথে, মাউসেও মাঝে ১০ সেকেন্ড পেছানো-এগোনো",
