/** The latest version of a lab. */
/**
 * O13: the version every subject page shows without `?lab=` (or with another lab's). It moves only when the
 * designer puts a newer LX version on the page; until then newer versions stay behind `?lab=lx_v<n>`.
 */
export const MAIN = { lab: "lx", v: 75 };

export const latest = (lab: Lab) => lab.versions[lab.versions.length - 1];

/**
 * CT213 (16 Nov): each page has its own versions, one link, and a version only when the designer says "lock".
 * `?lab=on` opens every page's working version (the link moves from page to page with it); `?lab=<id>@<n>` opens this
 * page's locked version n (other pages, seeing another page's id, show their working one). A lock freezes the working
 * version as the next number: add it to `locks` with `at: working`, then raise `working` by one; new changes are drawn
 * behind `version >= working`. The corner switch (`PageVersions`) lists the locks and the working one.
 */
export type PageSeries = {
  /** The page's key in the URL (`?lab=<id>@<n>`). */
  id: string;
  title: string;
  /** The working link's path and params, without `lab`. */
  path: string;
  /** The lab id the page's code asks (`labVersion(lab, …)`, `useLab(lab)`): its `version >= n` gates draw the page. */
  lab: string;
  /** Locked versions, oldest first: n is what the designer and the team see, `at` the gates' number it is drawn at. */
  locks: { n: number; at: number; date: string; name?: string; shots?: { desktop: string; phone: string } }[];
  /** The gates' number of the working version. */
  working: number;
};

const segmentShots = (v: number) => ({ desktop: `/labs/segment-home/v${v}-desktop.jpg`, phone: `/labs/segment-home/v${v}-phone.jpg` });

