/**
 * Rejected drafts, kept as pictures on the board `/bn/lab/board` (O6). From the decision log's
 * section 5; the pictures are screenshots taken while each draft was on review (from the session
 * records) or the audit's captures. Things that moved (the lantern, the night sky, the tag's swing)
 * are still pictures here. A newly rejected draft goes here in the same step, with its screenshot.
 */
